mapper.select:
SELECT 
  FROM tc_msg_send_queue
 WHERE topic = #{topic}
   AND idempotency_key = #{idempotencyKey}

SELECT 
  FROM tc_msg_send_queue
 WHERE status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
 ORDER BY next_retry_at ASC, msg_key ASC

    LIMIT #{limit} OFFSET #{offset}
